-- BrainRush: AI question set (owner request 2026-10-14)
--
-- Adds a new "AI" category with 30 easy, non-technical questions (5 per point
-- value, 100-600) and 84 AI-themed questions to the seven other categories
-- (Geography, Science, History, Sports, Movies, Technology, Gen Z; 2 per category
-- and point value, 100-600). Every row comes with its Arabic question and answer.
--
-- Requires sql/migrate-add-arabic.sql (or a schema that already has question_ar /
-- answer_ar). Run it on whichever database is selected (there is no USE line):
--   local:   mysql -u root brainrush < sql/add-ai-questions.sql
--   hosted:  phpMyAdmin -> select the database -> Import this file
-- It is safe to run again. The AI category is created only if it does not exist.
-- A row is skipped when its category was renamed or deleted, when its point value
-- does not exist, or when the category already has that question (INSERT IGNORE +
-- uq_category_question).

SET NAMES utf8mb4;

INSERT IGNORE INTO categories (name) VALUES ('AI');

DROP TEMPORARY TABLE IF EXISTS ai_seed;

CREATE TEMPORARY TABLE ai_seed (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  category_name VARCHAR(100) NOT NULL,
  points        INT UNSIGNED NOT NULL,
  question      TEXT         NOT NULL,
  answer        TEXT         NOT NULL,
  question_ar   TEXT         NOT NULL,
  answer_ar     TEXT         NOT NULL,
  PRIMARY KEY (id)
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;

